css:
.scene {
  position: relative;
  height: 260px;
  margin: 16px;
  overflow: hidden;
  border-radius: 16px;
  background-color: #fff7ed;
  font-family: system-ui, sans-serif;
}

.blob {
  position: absolute;
  width: 160px;
  height: 160px;
  border-radius: 50%;
}

.blob-a {
  top: 20px;
  left: 40px;
  background-color: #f97316;
}

.blob-b {
  right: 60px;
  bottom: 10px;
  background-color: #ec4899;
}

.glass {
  position: absolute;
  inset: 60px 80px;
  padding: 20px;
  border: 1px solid rgb(255 255 255 / 0.5);
  border-radius: 14px;
  background-color: rgb(255 255 255 / 0.35);
  box-shadow: 0 8px 24px rgb(0 0 0 / 0.12);
  backdrop-filter: blur(12px);
}

.glass-title {
  margin: 0 0 6px;
}

.glass-text {
  margin: 0;
}
